def mod(path,name):
 s=importlib.util.spec_from_file_location(name,path); m=importlib.util.module_from_spec(s); s.loader.exec_module(m); return m
def gid(x):
 s=str(x); return s[:-2] if s.endswith('.0') else s
def reg(y,p):
 y=np.asarray(y,float); p=np.asarray(p,float); ok=np.isfinite(y)&np.isfinite(p); y=y[ok]; p=p[ok]; e=p-y
 return {'n':len(y),'mae':np.mean(abs(e)),'median_absolute_error':np.median(abs(e)),'rmse':np.sqrt(np.mean(e*e)),'signed_bias':np.mean(e),'correlation':np.corrcoef(y,p)[0,1] if len(y)>2 and np.std(y)*np.std(p)>0 else np.nan,'within_1':np.mean(abs(e)<=1),'within_2':np.mean(abs(e)<=2),'within_3':np.mean(abs(e)<=3)}
def roi(v): return np.mean([100/110 if x=='W' else -1 if x=='L' else 0 for x in v]) if len(v) else np.nan
def fit_linear(x,y,alpha=1.0):
 x=np.asarray(x,float); y=np.asarray(y,float); med=np.nanmedian(x,axis=0); med=np.where(np.isfinite(med),med,0); x=np.where(np.isfinite(x),x,med); mu=x.mean(0); sd=np.where(x.std(0)>1e-9,x.std(0),1); z=(x-mu)/sd; a=np.c_[np.ones(len(z)),z]; pen=alpha*np.eye(a.shape[1]); pen[0,0]=0; b=np.linalg.solve(a.T@a+pen,a.T@y); return {'med':med,'mu':mu,'sd':sd,'b':b}
def predict_linear(model,x):
 x=np.asarray(x,float); x=np.where(np.isfinite(x),x,model['med']); z=(x-model['mu'])/model['sd']; return np.c_[np.ones(len(z)),z]@model['b']

def snapshot_audit():
 d=pd.concat([pd.read_csv(x) for x in SP],ignore_index=True); rows=[]
 for (s,w),z in d.groupby(['season','snapshot_week']): rows.append({'season':int(s),'snapshot_week':int(w),'teams':z.team.nunique(),'duplicate_team_rows':int(z.duplicated('team').sum()),'missing_overall':z.sp_plus.isna().sum(),'missing_offense':z.offense.isna().sum(),'missing_defense':z.defense.isna().sum(),'missing_special_teams':z.special_teams.isna().sum(),'tempo_present':False,'source_file':str((SP[0] if s<2025 else SP[1]).relative_to(ROOT))})
 a=pd.DataFrame(rows); summary={'sources':[str(x.relative_to(ROOT)) for x in SP],'genuine_weekly_observations':True,'weeks_by_season':{str(int(s)):sorted(map(int,z.snapshot_week.unique())) for s,z in d.groupby('season')},'defense_sign_convention':'lower raw defensive SP+ is better because overall = offense - defense + special teams','defense_improvement_formula':'actual_defense_improvement = -actual_sp_def_change','offense_sign_convention':'higher offensive SP+ is better','units':'SP+ rating points','tempo_present':False,'missing_weeks_not_bridged':True}; return a,summary

def component_models(base,m,train,sel,hold,target,features,rules_col):
 d=base.copy(); d['actual_market_rating_change']=d[target]; d['rules_repeatable_spread']=d[rules_col]; best,grid=m.select_model(d,features,train,sel); th=float(best['threshold']); out=[]
 for season in train+[sel,hold]:
  fits=[x for x in train if x!=season] if season in train else train if season==sel else train+[sel]
  model=m.fit_models(d,features,th,fits); z=d[d.season==season].copy(); p=m.predict_models(z,model)
  for k,v in p.items(): z[k]=v
  fam=best['direction_model']
  if fam=='ordinal_ridge_proxy': z['component_direction']=m.movement_class(z.ridge,th); probs=m.movement_probs_from_score(z.ridge,th)
  elif fam=='rules_based': z['component_direction']=m.movement_class(z[rules_col],th); probs=m.movement_probs_from_score(z[rules_col],th)
  elif fam=='gradient_boosted_stumps': z['component_direction']=m.movement_class(z.boosted_challenger,th); probs=m.movement_probs_from_score(z.boosted_challenger,th)
  else: probs=np.c_[z.prob_down,z.prob_no_change,z.prob_up]
  z[['component_prob_down','component_prob_no_change','component_prob_up']]=probs; z['component_predicted_change']=z[str(best['magnitude_model'])]; z['component_actual_direction']=m.movement_class(z[target],th); z['fit_seasons']=','.join(map(str,fits)); z['prediction_oos']=True; z['split']='train_crossfit' if season in train else 'selection' if season==sel else 'locked_holdout'; out.append(z)
 p=pd.concat(out,ignore_index=True); return p,best,grid

def build_games(off,defn,core,existing):
 core=core.copy(); core['game_id']=core.game_id.map(gid); existing=existing.copy(); existing['game_id']=existing.game_id.map(gid)
 o=off[off.next_game_id.notna()].copy(); o['next_game_id']=o.next_game_id.map(gid); d=defn[defn.next_game_id.notna()].copy(); d['next_game_id']=d.next_game_id.map(gid); rows=[]
 for (season,game),z in o.groupby(['season','next_game_id']):
  gg=core[(core.season==season)&(core.game_id==game)]; dz=d[(d.season==season)&(d.next_game_id==game)]
  if gg.empty: continue
  g=gg.iloc[0]; sides=[z[z.team==g.home_team].tail(1),z[z.team==g.away_team].tail(1),dz[dz.team==g.home_team].tail(1),dz[dz.team==g.away_team].tail(1)]
  if any(x.empty for x in sides): continue
  ho,ao,hd,ad=[x.iloc[0] for x in sides]; e=existing[(existing.season==season)&(existing.game_id==game)]
  rows.append({'season':int(season),'week':int(g.week),'game_id':game,'away_team':g.away_team,'home_team':g.home_team,'actual_home_points':g.home_score,'actual_away_points':g.away_score,'current_home_sp_offense':ho.current_sp_plus_offense,'predicted_home_off_change':ho.component_predicted_change,'predicted_updated_home_offense':ho.current_sp_plus_offense+ho.component_predicted_change,'current_away_sp_offense':ao.current_sp_plus_offense,'predicted_away_off_change':ao.component_predicted_change,'predicted_updated_away_offense':ao.current_sp_plus_offense+ao.component_predicted_change,'current_home_sp_defense':hd.current_sp_plus_defense,'predicted_home_def_change':-hd.component_predicted_change,'predicted_updated_home_defense':hd.current_sp_plus_defense-hd.component_predicted_change,'current_away_sp_defense':ad.current_sp_plus_defense,'predicted_away_def_change':-ad.component_predicted_change,'predicted_updated_away_defense':ad.current_sp_plus_defense-ad.component_predicted_change,'home_prior_pace':ho.off_game_clock_seconds_per_play,'away_prior_pace':ao.off_game_clock_seconds_per_play,'home_prior_plays':ho.off_plays,'away_prior_plays':ao.off_plays,'home_feature_coverage':ho.notna().mean(),'away_feature_coverage':ao.notna().mean(),'frozen_market_baseline_total':e.frozen_combined_total_baseline.iloc[0] if len(e) else np.nan,'existing_total_projection':e.projected_close.iloc[0] if len(e) else np.nan,'current_lambda_085_projection':e.current_lambda_085_projection.iloc[0] if len(e) else np.nan,'raw_prior_total_residual':(ho.total_residual+ao.total_residual)/2,'repeatable_total_adjustment':ho.repeatable_total_performance+ao.repeatable_total_performance,'opening_total_timing_unknown':g.opening_total,'actual_close':g.closing_total,'actual_total':g.home_score+g.away_score,'timing_limitation_flag':'TIMING-UNKNOWN ESPN BET OPENING-FIELD DIAGNOSTIC; not proven Saturday DK/FD','neutral_site_status':'unavailable/uncertain','component_prediction_oos':True})
 return pd.DataFrame(rows)

def total_models(games,train,sel,hold):
 pure=['predicted_updated_home_offense','predicted_updated_away_offense','predicted_updated_home_defense','predicted_updated_away_defense']; pace=pure+['home_prior_pace','away_prior_pace','home_prior_plays','away_prior_plays']; residual=['predicted_home_off_change','predicted_away_off_change','predicted_home_def_change','predicted_away_def_change','repeatable_total_adjustment']
 fit=games[games.season.isin(train)]; models={'pure_components':fit_linear(fit[pure],fit.actual_close,10),'market_baseline_residual':fit_linear(fit[residual],fit.actual_close-fit.frozen_market_baseline_total,10)}
 point_cols=['team_offense','opponent_defense','home_indicator','team_prior_pace','opponent_prior_pace','team_prior_plays','opponent_prior_plays']; px=[]; py=[]
 for r in fit.itertuples():
  px.append([r.predicted_updated_home_offense,r.predicted_updated_away_defense,1,r.home_prior_pace,r.away_prior_pace,r.home_prior_plays,r.away_prior_plays]); py.append(r.actual_home_points)
  px.append([r.predicted_updated_away_offense,r.predicted_updated_home_defense,0,r.away_prior_pace,r.home_prior_pace,r.away_prior_plays,r.home_prior_plays]); py.append(r.actual_away_points)
 models['team_points']=fit_linear(np.asarray(px),np.asarray(py),10)
 hx=np.c_[games.predicted_updated_home_offense,games.predicted_updated_away_defense,np.ones(len(games)),games.home_prior_pace,games.away_prior_pace,games.home_prior_plays,games.away_prior_plays]; ax=np.c_[games.predicted_updated_away_offense,games.predicted_updated_home_defense,np.zeros(len(games)),games.away_prior_pace,games.home_prior_pace,games.away_prior_plays,games.home_prior_plays]
 games['predicted_home_points']=predict_linear(models['team_points'],hx); games['predicted_away_points']=predict_linear(models['team_points'],ax); games['pure_sp_plus_total']=predict_linear(models['pure_components'],games[pure]); games['pace_sp_plus_total']=games.predicted_home_points+games.predicted_away_points
 games['market_plus_sp_residual']=games.frozen_market_baseline_total+predict_linear(models['market_baseline_residual'],games[residual])
 # Select SP formulation and blend on 2024 only.
 z=games[games.season==sel]; spchoice=min(['pure_sp_plus_total','pace_sp_plus_total'],key=lambda c:(z[c]-z.actual_close).abs().mean()); weights=np.arange(0,1.01,.1); score={float(w):float((w*z[spchoice]+(1-w)*z.existing_total_projection-z.actual_close).abs().mean()) for w in weights}; w=min(score,key=score.get)
 games['selected_sp_component_total']=games[spchoice]; games['simple_50_50_blend']=.5*games.selected_sp_component_total+.5*games.existing_total_projection; games['optimized_fixed_blend']=w*games.selected_sp_component_total+(1-w)*games.existing_total_projection
 candidates=['existing_total_projection','selected_sp_component_total','simple_50_50_blend','optimized_fixed_blend','market_plus_sp_residual']; choice=min(candidates,key=lambda c:((z[c] if c in z else games.loc[z.index,c])-z.actual_close).abs().mean()); games['selected_blended_shadow_total']=games[choice]
 diff=(games.selected_sp_component_total-games.existing_total_projection).abs(); q50=float(diff[games.season==sel].median()); q75=float(diff[games.season==sel].quantile(.75)); games['model_agreement_category']=np.where(diff<=q50,'Strong agreement',np.where(diff<=q75,'Moderate agreement','Conflict')); games['total_confidence']=np.where(games[['home_feature_coverage','away_feature_coverage']].min(axis=1)<.7,'Insufficient data',np.where(diff<=q50,'High confidence',np.where(diff<=q75,'Medium confidence','Conflict')))
 raw_coef=models['team_points']['b'][1:]/models['team_points']['sd']; raw_intercept=models['team_points']['b'][0]-np.sum(models['team_points']['b'][1:]*models['team_points']['mu']/models['team_points']['sd'])
 selection={'sp_component_formula':spchoice,'team_points_formula':{'intercept':float(raw_intercept),'coefficients':{c:float(v) for c,v in zip(point_cols,raw_coef)}},'pace_improved_2024':spchoice=='pace_sp_plus_total','optimized_sp_weight':w,'selected_total_model':choice,'confidence_difference_thresholds':{'high_max':q50,'medium_max':q75},'selected_without_2025':True,'conversion_fit_seasons':train}; return games,selection,models

def compare(g,sel,hold):
 models={'no_total_update':'frozen_market_baseline_total','frozen_market_total_baseline':'frozen_market_baseline_total','current_production_shadow_total':'existing_total_projection','current_lambda_0.85':'current_lambda_085_projection','predicted_combined_market_total_movement':'existing_total_projection','raw_final_score_total_adjustment':'raw_total_projection','raw_PBP_total_adjustment':'raw_pbp_total_projection','predicted_SP_components':'selected_sp_component_total','market_plus_SP_residual':'market_plus_sp_residual','simple_50_50_blend':'simple_50_50_blend','optimized_fixed_blend':'optimized_fixed_blend','selected_blended_total':'selected_blended_shadow_total','historical_ESPN_Bet_opening_total':'opening_total_timing_unknown'}
 g['raw_total_projection']=g.frozen_market_baseline_total+.15*g.raw_prior_total_residual; g['raw_pbp_total_projection']=g.frozen_market_baseline_total+.20*g.repeatable_total_adjustment
 # Identical sample across all candidate fields and close.
 cols=list(dict.fromkeys(models.values()))+['actual_close']; identical=g[cols].notna().all(axis=1); rows=[]
 for season in [sel,hold]:
  z=g[(g.season==season)&identical]
  for name,c in models.items(): rows.append({'season':season,'model':name,'identical_sample':True,**reg(z.actual_close,z[c])})
 return pd.DataFrame(rows),identical

def diagnostics(g,hold):
 z=g[g.season==hold].copy(); rows=[]
 for tier,q in z.groupby('total_confidence'):
  b=q[q.opening_total_timing_unknown.notna()].copy(); b['side']=np.where(b.selected_blended_shadow_total>b.opening_total_timing_unknown,'Over','Under'); b['clv']=np.where(b.side=='Over',b.actual_close-b.opening_total_timing_unknown,b.opening_total_timing_unknown-b.actual_close); b['result']=np.where(((b.side=='Over')&(b.actual_total>b.opening_total_timing_unknown))|((b.side=='Under')&(b.actual_total<b.opening_total_timing_unknown)),'W',np.where(b.actual_total==b.opening_total_timing_unknown,'P','L')); rows.append({'confidence':tier,'games':len(q),'closing_total_mae':(q.selected_blended_shadow_total-q.actual_close).abs().mean(),'positive_clv_rate':(b.clv>0).mean(),'average_clv':b.clv.mean(),'median_clv':b.clv.median(),'directional_accuracy':(np.sign(b.selected_blended_shadow_total-b.opening_total_timing_unknown)==np.sign(b.actual_close-b.opening_total_timing_unknown)).mean(),'win_rate':(b.result=='W').sum()/max(b.result.isin(['W','L']).sum(),1),'roi_at_minus_110':roi(b.result)})
 return pd.DataFrame(rows)

