 train_mask=features.season.isin(a.train_seasons); off_features=[x for x in off_features if features.loc[train_mask,x].notna().any()]; def_features=[x for x in def_features if features.loc[train_mask,x].notna().any()]
 off,ob,og=component_models(features,m,a.train_seasons,a.selection_season,a.holdout_season,'actual_sp_plus_offense_change',off_features,'repeatable_offense_performance'); de,db,dg=component_models(features,m,a.train_seasons,a.selection_season,a.holdout_season,'actual_defense_improvement',def_features,'repeatable_defense_performance')
 core=pd.read_csv(CORE,low_memory=False); existing=pd.read_csv(MOV/'next_game_total_predictions.csv'); games=build_games(off,de,core,existing); games,tsel,conversion=total_models(games,a.train_seasons,a.selection_season,a.holdout_season); comparison,identical=compare(games,a.selection_season,a.holdout_season); conf=diagnostics(games,a.holdout_season)
